/**
 * The Mandarin syllabary in pinyin, bopomofo, Wade-Giles, Yale, Gwoyeu Romatzyh
 * and IPA.
 *
 * Taken from Wikipedia's *Comparison of Chinese transcription systems* (CC
 * BY-SA 4.0, retrieved 2026-08-04) and committed rather than fetched, so that
 * the check runs offline and an edit to the page cannot move the target without
 * a reviewable diff.
 *
 * It is here because the romanisation tables would otherwise be unfalsifiable.
 * Every other claim in this package is scored against data — readings against
 * CC-CEDICT, polyphones against CPP — and no source in the pipeline carries any
 * of these systems, so without this the tables would rest on whatever the
 * author believed while typing them.
 *
 * Kept exactly as the source writes it: `ʻ` is the turned comma rather than the
 * ASCII apostrophe this package writes, a `/` in the source becomes a second
 * entry, since several syllables have two attested Wade-Giles forms, and the
 * trailing `?` on 哦 o's Yale and IPA cells is the source marking that row as
 * unverified rather than a character either system writes.
 *
 * The Yale and IPA columns were taken from the same page and the same revision
 * on 2026-08-04, and the three columns that were already here were regenerated
 * from that parse and matched all 417 rows unchanged — which is the only
 * available check that the second reading of the page is the same reading as
 * the first. The four Gwoyeu Romatzyh columns were added on 2026-08-05 the same
 * way, and the five already here were regenerated again and again matched
 * unchanged.
 */

/**
 * One syllable, written six ways.
 */
export interface SyllabaryRow {
  readonly pinyin: string;
  readonly bopomofo: string;
  /** Every Wade-Giles form the source gives, in the order it gives them. */
  readonly wadeGiles: readonly string[];
  readonly yale: string;
  /**
   * The four Gwoyeu Romatzyh spellings, one per tone, in tone order.
   *
   * Four rather than one because GR spells the tone into the syllable: 山 shān
   * is `shan` and 善 shàn is `shann`. The neutral tone has no column, since it
   * is written as a dot in front of whichever of these four the syllable would
   * otherwise take.
   */
  readonly gwoyeu: readonly [string, string, string, string];
  /**
   * The source's own broad transcription, with no tone letters.
   *
   * Broader than the key of *Help:IPA/Mandarin*, which is a different page:
   * [ipa-mandarin.ts](ipa-mandarin.ts) holds that one and records every place
   * the two part.
   */
  readonly ipa: string;
}

